using System.ComponentModel.DataAnnotations;

namespace MyFirstApp.Models
{
    public class ContactForm
    {
        [Required(ErrorMessage = "Please enter your name")]
        [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters")]
        public string Name { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please enter your email address")]
        [EmailAddress(ErrorMessage = "Please enter a valid email address")]
        public string Email { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please enter a message")]
        [StringLength(1000, ErrorMessage = "Message cannot exceed 1000 characters")]
        public string Message { get; set; } = string.Empty;
    }
}

// In HomeController
[HttpGet]
public IActionResult Contact() => View();

[HttpPost]
[ValidateAntiForgeryToken]
public IActionResult Contact(ContactForm model)
{
    if (!ModelState.IsValid)
    {
        // Validation failed — re-render the form with error messages
        return View(model);
    }

    // Process the valid form data
    _emailService.Send(model.Email, "Contact Form", model.Message);

    TempData["SuccessMessage"] = "Your message has been sent!";
    return RedirectToAction(nameof(Contact)); // POST-Redirect-GET
}
